// Source-curve, projected-relation and answer checker using OpenSSL, not GMP.
// It does not verify the auxiliary Jacobian/quotient construction.
#include "openssl_core.hpp"
long fp,aa,bb;
long mod(long x){return (x%fp+fp)%fp;}
long pow_small(long a,long n,long p){long r=1;while(n){if(n&1)r=r*a%p;a=a*a%p;n>>=1;}return r;}
long inverse_fp(long a){a=mod(a);require(a!=0,"checker field inverse");return pow_small(a,fp-2,fp);}
Point multiply(const EC_GROUP*g,const EC_POINT*p,long n,BN_CTX*ctx){auto out=point(g);Big scalar(BN_new(),BN_free);require(bool(scalar)&&BN_set_word(scalar.get(),static_cast<unsigned long>(n))==1&&EC_POINT_mul(g,out.get(),nullptr,p,scalar.get(),ctx)==1,"checker point multiply");return out;}
Point affine(const EC_GROUP*g,long x,long y,BN_CTX*ctx){auto out=point(g);auto bx=decimal(std::to_string(x)),by=decimal(std::to_string(y));require(EC_POINT_set_affine_coordinates(g,out.get(),bx.get(),by.get(),ctx)==1&&EC_POINT_is_on_curve(g,out.get(),ctx)==1,"checker support elliptic point");return out;}
Point image(const EC_GROUP*g,long X,long Y,BN_CTX*ctx){long c=1024%fp;if(X==0)return affine(g,1,mod(pow_small(c,4,fp)*Y),ctx);long t=mod(1+inverse_fp(c*X)),den=mod(t*t-1);if(den==0){auto out=point(g);require(EC_POINT_set_to_infinity(g,out.get())==1,"checker branch infinity");return out;}return affine(g,mod((t*t+7)*inverse_fp(den)),mod(Y*inverse_fp(pow_small(X,4,fp)*mod(den*den))),ctx);}
long cover_value(long X){long c=1024%fp;if(X==0)return mod((1+aa+bb)*inverse_fp(pow_small(c,8,fp)));long t=mod(1+inverse_fp(c*X)),A=mod(t*t+7),B=mod(t*t-1);return mod(pow_small(X,8,fp)*mod(B*mod(pow_small(A,3,fp)+aa*A%fp*B%fp*B+bb*pow_small(B,3,fp))));}
int rank_rows(std::vector<std::vector<long>> rows,int cols,long r){int rank=0;for(int c=0;c<cols;++c){int pivot=rank;while(pivot<int(rows.size())&&rows[pivot][c]==0)++pivot;if(pivot==int(rows.size()))continue;std::swap(rows[pivot],rows[rank]);long inv=pow_small(rows[rank][c],r-2,r);for(auto&x:rows[rank])x=x*inv%r;for(int i=0;i<int(rows.size());++i)if(i!=rank){long z=rows[i][c];for(int j=0;j<cols;++j)rows[i][j]=(rows[i][j]-z*rows[rank][j]%r+r)%r;}++rank;}return rank;}
int main(int argc,char**argv){try{require(argc==2||(argc==3&&std::string(argv[2])=="--canary"),"usage: openssl_toy_check public-witness.json [--canary]");bool canary=argc==3;auto receipt=read_json(argv[1]);require(receipt.at("schema").scalar=="toy.ic.correctness/v1","checker schema");fp=receipt.at("p").integer();aa=receipt.at("a").integer();bb=receipt.at("b").integer();require(fp==109||fp==1009,"checker frozen prime panel");require(aa==mod(-864)&&bb==mod(-5616),"checker Hesse source");long n=receipt.at("source_order").integer(),r=receipt.at("r").integer(),cofactor=receipt.at("cofactor").integer();require(n==r*cofactor&&r>3,"checker subgroup/cofactor");for(long d=2;d*d<=r;++d)require(r%d!=0,"checker subgroup primality");long count=1;for(long x=0;x<fp;++x)for(long y=0;y<fp;++y)count+=mod(y*y)==mod(x*x*x+aa*x+bb);require(count==n,"checker exact source count");
    std::unique_ptr<BN_CTX,decltype(&BN_CTX_free)> ctx(BN_CTX_new(),BN_CTX_free);auto p=decimal(std::to_string(fp)),a=decimal(std::to_string(aa)),b=decimal(std::to_string(bb));std::unique_ptr<EC_GROUP,decltype(&EC_GROUP_free)> group(EC_GROUP_new_curve_GFp(p.get(),a.get(),b.get(),ctx.get()),EC_GROUP_free);require(bool(group),"checker OpenSSL curve");auto generator=read_point(receipt.at("generator"),group.get(),ctx.get());require(EC_POINT_is_at_infinity(group.get(),generator.get())==0&&EC_POINT_is_at_infinity(group.get(),multiply(group.get(),generator.get(),r,ctx.get()).get())==1,"checker generator order");
    std::vector<Point> base;std::vector<long> logs;for(auto&entry:receipt.at("base").arr){auto value=read_point(entry.at("point"),group.get(),ctx.get());long log=entry.at("log").integer();require(log>0&&log<r,"checker base logarithm range");auto expected=multiply(group.get(),generator.get(),log,ctx.get());require(EC_POINT_cmp(group.get(),value.get(),expected.get(),ctx.get())==0,"checker base logarithm");for(auto&old:base)require(EC_POINT_cmp(group.get(),old.get(),value.get(),ctx.get())!=0,"checker projected duplicate");base.push_back(std::move(value));logs.push_back(log);}require(!base.empty()&&logs[0]==1,"checker generator anchor");
    std::vector<std::vector<long>> matrix;std::vector<long> anchor(base.size());anchor[0]=1;matrix.push_back(anchor);int relations=0,support_count=0;
    for(auto&relation:receipt.at("relations").arr){require(relation.at("L").arr.size()==4&&relation.at("support").arr.size()==7&&relation.at("row").arr.size()==base.size(),"checker relation shape");std::vector<long> expected(base.size()),row;std::set<long> support;
        for(auto&pair:relation.at("support").arr){require(pair.arr.size()==2,"checker support pair");long X=pair.arr[0].integer(),Y=pair.arr[1].integer();require(X>=0&&X<fp&&Y>=0&&Y<fp&&support.insert(X).second,"checker distinct canonical support");long line=0;for(int i=3;i>=0;--i)line=mod(line*X+relation.at("L").arr[i].integer());require(line==Y&&mod(Y*Y)==cover_value(X),"checker principal-function support");auto projected=multiply(group.get(),image(group.get(),X,Y,ctx.get()).get(),3*cofactor,ctx.get());if(EC_POINT_is_at_infinity(group.get(),projected.get())==0){int found=-1;for(int i=0;i<int(base.size());++i)if(EC_POINT_cmp(group.get(),projected.get(),base[i].get(),ctx.get())==0){found=i;break;}require(found>=0,"checker projected support base");expected[found]=(expected[found]+1)%r;}++support_count;}
        for(auto&c:relation.at("row").arr){long x=c.integer();require(x>=0&&x<r,"checker row coefficient");row.push_back(x);}if(canary&&relations==0)row[0]=(row[0]+1)%r;require(row==expected,"checker projected row mismatch");auto sum=point(group.get());require(EC_POINT_set_to_infinity(group.get(),sum.get())==1,"checker relation origin");for(size_t i=0;i<row.size();++i){auto term=multiply(group.get(),base[i].get(),row[i],ctx.get());require(EC_POINT_add(group.get(),sum.get(),sum.get(),term.get(),ctx.get())==1,"checker relation sum");}require(EC_POINT_is_at_infinity(group.get(),sum.get())==1,"checker false relation");matrix.push_back(row);++relations;
    }int rank=rank_rows(matrix,int(base.size()),r);require(rank==int(base.size()),"checker relation matrix rank");std::set<long> recovered;int targets=0;for(auto&entry:receipt.at("targets").arr){long k=entry.at("recovered").integer();require(k>=0&&k<r&&recovered.insert(k).second,"checker target scalar uniqueness");auto target=read_point(entry.at("point"),group.get(),ctx.get());auto answer=multiply(group.get(),generator.get(),k,ctx.get());require(EC_POINT_cmp(group.get(),target.get(),answer.get(),ctx.get())==0,"checker recovered answer");++targets;}require(targets==r,"checker all subgroup targets");require(!canary,"checker corruption not rejected");std::cout<<"PASS OpenSSL source_order="<<n<<" prime_subgroup="<<r<<" base_logs="<<base.size()<<" principal_supports="<<support_count<<" projected_relations="<<relations<<" rank="<<rank<<" source_verified_answers="<<targets<<"; auxiliary Jacobian/kernel construction is outside this check\n";
}catch(const std::exception&e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
